<script setup lang="ts">import {usePropertyStore} from '@/hooks/property';import {pixelDefaults} from '@/pixel-clock';const property=usePropertyStore();const toggles={showSeconds:'显示秒',blink:'冒号闪烁',glow:'灯点柔光'};</script>
<template><section><h3>像素点阵时钟</h3><p>方形灯点 · 固定字格 · 本地时间</p><label v-for="(title,key) in toggles">{{title}}<input type="checkbox" :checked="property.settings[key]??pixelDefaults[key]" @change="property.settings[key]=($event.target as HTMLInputElement).checked"></label><label>灯点颜色<input type="color" :value="property.settings.color??pixelDefaults.color" @input="property.settings.color=($event.target as HTMLInputElement).value"></label><label>亮度 {{property.settings.brightness??90}}%<input type="range" min="10" max="100" :value="property.settings.brightness??90" @input="property.settings.brightness=Number(($event.target as HTMLInputElement).value)"></label></section></template>
